-- Article 3: Cómo comprar por mayor sin complicarte
INSERT INTO `blog_post` (`title`, `slug`, `summary`, `content`, `cover_image_path`, `status`, `created_at`, `published_at`) VALUES
('Cómo comprar por mayor sin complicarte', 'como-consultar-precios-por-mayor-sin-complicarte', 'Qué datos enviar por WhatsApp para recibir una respuesta rápida cuando compras para negocio, restaurante o reventa.', '
<h2>Comprar por mayor es más fácil si envías datos claros</h2>
<p>Cuando alguien consulta por mayor, normalmente necesita precio, cantidad, presentación, disponibilidad y forma de entrega. Si el mensaje llega incompleto, la respuesta se demora porque primero hay que pedir más información.</p>
<p>Para ayudarte más rápido, lo mejor es enviar desde el inicio qué producto necesitas, en qué cantidad, para cuándo y en qué zona deseas coordinar.</p>
<p style="background:#ecfdf5;border-left:4px solid #16a34a;padding:12px 14px;border-radius:10px;margin:16px 0;"><strong>Nota:</strong> La disponibilidad puede variar por temporada. Antes de comprar por cantidad, confirma stock y presentación por WhatsApp.</p>
<h2>Datos que debes enviar</h2>
<div style="overflow-x:auto;margin:16px 0;"><table style="width:100%;border-collapse:collapse;font-size:15px;"><thead><tr><th style="border:1px solid #d1d5db;padding:10px;background:#166534;color:#fff;text-align:left;">Dato</th><th style="border:1px solid #d1d5db;padding:10px;background:#166534;color:#fff;text-align:left;">Ejemplo recomendado</th></tr></thead><tbody><tr><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Producto</td><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Paiche seco, hoja de bijao, pescado ahumado, cecina, frutas o harinas.</td></tr><tr><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Cantidad</td><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">10 kg, 5 paquetes, 100 hojas, 20 unidades o cantidad aproximada.</td></tr><tr><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Tipo de compra</td><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Por menor, por mayor, para restaurante, para reventa o para evento.</td></tr><tr><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Zona de entrega</td><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Iquitos, distrito, referencia o punto de coordinación.</td></tr><tr><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Fecha aproximada</td><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Hoy, mañana, esta semana, antes de una fecha especial.</td></tr><tr><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Observación</td><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Si necesitas una presentación específica, producto más seco, hojas grandes, etc.</td></tr></tbody></table></div>
<h2>Mensaje modelo para copiar</h2>
<blockquote style="border-left:4px solid #16a34a;background:#f0fdf4;padding:14px 16px;border-radius:10px;margin:16px 0;">Hola, quisiera consultar por <strong>paiche seco por mayor</strong>. Necesito aproximadamente <strong>10 kg</strong> para <strong>Iquitos</strong>, entrega esta semana. ¿Tienen disponibilidad y precio actualizado?</blockquote>
<h2>Productos que suelen consultarse por mayor</h2>
<div style="overflow-x:auto;margin:16px 0;"><table style="width:100%;border-collapse:collapse;font-size:15px;"><thead><tr><th style="border:1px solid #d1d5db;padding:10px;background:#166534;color:#fff;text-align:left;">Producto</th><th style="border:1px solid #d1d5db;padding:10px;background:#166534;color:#fff;text-align:left;">Uso frecuente</th><th style="border:1px solid #d1d5db;padding:10px;background:#166534;color:#fff;text-align:left;">Recomendación</th></tr></thead><tbody><tr><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Paiche seco</td><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Restaurantes, hogares y eventos.</td><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Confirmar peso, presentación y disponibilidad.</td></tr><tr><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Hojas de bijao</td><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Juanes, tamales y comidas tradicionales.</td><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Comprar con anticipación en temporada alta.</td></tr><tr><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Hojas de plátano</td><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Preparaciones amplias, vapor y parrilla.</td><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Indicar si se necesitan hojas grandes.</td></tr><tr><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Ahumados</td><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Negocios de comida y consumo familiar.</td><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Consultar si son para consumo rápido o almacenamiento.</td></tr><tr><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Pescado seco variado</td><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Reventa y cocina tradicional.</td><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Confirmar tipo de pescado y cantidad.</td></tr></tbody></table></div>
<div style="background:#f8fafc;border:1px solid #e5e7eb;border-radius:14px;padding:16px;margin:16px 0;"><h3 style="margin-top:0;">Checklist rápido</h3><ul style="margin-bottom:0;list-style:none;padding-left:0;"><li style="margin-bottom:8px;">✅ Definir producto y cantidad.</li><li style="margin-bottom:8px;">✅ Confirmar si es precio por mayor o menor.</li><li style="margin-bottom:8px;">✅ Indicar zona de entrega.</li><li style="margin-bottom:8px;">✅ Pedir confirmación de disponibilidad antes de cerrar.</li></ul></div>
<h2>Ventajas de consultar bien</h2>
<p>Un mensaje claro permite confirmar stock, evitar confusiones, coordinar mejor la entrega y responder con mayor precisión. También ayuda a separar productos cuando la disponibilidad es limitada.</p>
<div style="background:#fff7ed;border:1px solid #fed7aa;border-radius:14px;padding:16px;margin:16px 0;"><h3 style="margin-top:0;">Nivel recomendado</h3><div style="margin:10px 0;"><div style="display:flex;justify-content:space-between;font-size:14px;"><strong>Respuesta más rápida</strong><span>95%</span></div><div style="background:#e5e7eb;border-radius:999px;height:10px;"><div style="width:95%;height:10px;border-radius:999px;background:#16a34a;"></div></div></div><div style="margin:10px 0;"><div style="display:flex;justify-content:space-between;font-size:14px;"><strong>Menos confusiones</strong><span>90%</span></div><div style="background:#e5e7eb;border-radius:999px;height:10px;"><div style="width:90%;height:10px;border-radius:999px;background:#16a34a;"></div></div></div><div style="margin:10px 0;"><div style="display:flex;justify-content:space-between;font-size:14px;"><strong>Mejor coordinación</strong><span>85%</span></div><div style="background:#e5e7eb;border-radius:999px;height:10px;"><div style="width:85%;height:10px;border-radius:999px;background:#16a34a;"></div></div></div><div style="margin:10px 0;"><div style="display:flex;justify-content:space-between;font-size:14px;"><strong>Pedido sin datos</strong><span>25%</span></div><div style="background:#e5e7eb;border-radius:999px;height:10px;"><div style="width:25%;height:10px;border-radius:999px;background:#16a34a;"></div></div></div></div>
<h2>Conclusión</h2>
<p>Comprar por mayor no tiene que ser complicado. Mientras más claro sea tu mensaje, más fácil será confirmar disponibilidad, precio y coordinación.</p>
<div style="background:#0f766e;color:#fff;padding:18px;border-radius:14px;margin-top:22px;"><h3 style="margin-top:0;color:#fff;">Consulta por WhatsApp</h3><p style="margin-bottom:0;">Escríbenos indicando producto, cantidad, zona y fecha aproximada. Te ayudamos a coordinar tu pedido por WhatsApp.</p></div>
', '/uploads/belen/blog/03-compras-por-mayor.jpg', 'PUBLISHED', '2026-05-28 20:30:00', '2026-05-28 20:30:00')
