-- Article 4: Productos amazónicos para temporada de San Juan
INSERT INTO `blog_post` (`title`, `slug`, `summary`, `content`, `cover_image_path`, `status`, `created_at`, `published_at`) VALUES
('Productos amazónicos para temporada de San Juan', 'productos-amazonicos-para-temporada-de-san-juan', 'Ideas de productos que suelen tener alta demanda en temporada de San Juan y cómo pedir con anticipación.', '
<h2>San Juan mueve la cocina amazónica</h2>
<p>La temporada de San Juan es una de las fechas más importantes para los productos amazónicos. En esos días muchas familias, restaurantes y negocios buscan hojas, pescados, ahumados y otros insumos para preparar comidas tradicionales.</p>
<p>Por eso, si necesitas comprar para tu casa, negocio o evento, lo mejor es consultar disponibilidad con anticipación. Algunos productos pueden agotarse rápido o variar de precio según la demanda.</p>
<p style="background:#ecfdf5;border-left:4px solid #16a34a;padding:12px 14px;border-radius:10px;margin:16px 0;"><strong>Nota:</strong> La disponibilidad puede variar por temporada. Antes de comprar por cantidad, confirma stock y presentación por WhatsApp.</p>
<h2>Productos con mayor movimiento en temporada</h2>
<div style="overflow-x:auto;margin:16px 0;"><table style="width:100%;border-collapse:collapse;font-size:15px;"><thead><tr><th style="border:1px solid #d1d5db;padding:10px;background:#166534;color:#fff;text-align:left;">Producto</th><th style="border:1px solid #d1d5db;padding:10px;background:#166534;color:#fff;text-align:left;">Uso frecuente en temporada</th><th style="border:1px solid #d1d5db;padding:10px;background:#166534;color:#fff;text-align:left;">Recomendación</th></tr></thead><tbody><tr><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Hoja de bijao</td><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Juanes y comidas tradicionales.</td><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Consultar paquetes con anticipación.</td></tr><tr><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Hoja de plátano</td><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Envolturas grandes, cocción al vapor y presentación.</td><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Indicar tamaño o cantidad aproximada.</td></tr><tr><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Paiche seco</td><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Platos típicos, consumo familiar y restaurantes.</td><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Confirmar disponibilidad y presentación.</td></tr><tr><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Pescados secos</td><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Cocina tradicional y pedidos por volumen.</td><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Preguntar por variedad disponible.</td></tr><tr><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Ahumados</td><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Complementos para platos y negocios de comida.</td><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Comprar según fecha de uso.</td></tr></tbody></table></div>
<h2>¿Por qué pedir antes?</h2>
<ul><li>Te permite separar productos según disponibilidad.</li><li>Evita quedarte sin hojas o pescado en fechas fuertes.</li><li>Ayuda a coordinar mejor entrega o punto de recojo.</li><li>Permite comparar si necesitas por menor o por mayor.</li></ul>
<div style="background:#f8fafc;border:1px solid #e5e7eb;border-radius:14px;padding:16px;margin:16px 0;"><h3 style="margin-top:0;">Checklist rápido</h3><ul style="margin-bottom:0;list-style:none;padding-left:0;"><li style="margin-bottom:8px;">✅ Consulta mínimo unos días antes si es para negocio.</li><li style="margin-bottom:8px;">✅ Indica cantidad exacta o aproximada.</li><li style="margin-bottom:8px;">✅ Pregunta si el producto está disponible en la presentación que necesitas.</li><li style="margin-bottom:8px;">✅ Confirma fecha y punto de entrega.</li></ul></div>
<h2>Ideas para hogares y negocios</h2>
<div style="overflow-x:auto;margin:16px 0;"><table style="width:100%;border-collapse:collapse;font-size:15px;"><thead><tr><th style="border:1px solid #d1d5db;padding:10px;background:#166534;color:#fff;text-align:left;">Tipo de cliente</th><th style="border:1px solid #d1d5db;padding:10px;background:#166534;color:#fff;text-align:left;">Productos sugeridos</th></tr></thead><tbody><tr><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Hogar</td><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Hojas de bijao, pescado seco, ahumados y frutas según disponibilidad.</td></tr><tr><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Restaurante</td><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Hojas por paquete, paiche seco, pescado seco variado y ahumados.</td></tr><tr><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Bodega o reventa</td><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Productos secos, harinas, dulces y presentaciones de mayor duración.</td></tr><tr><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Evento familiar</td><td style="border:1px solid #d1d5db;padding:10px;vertical-align:top;">Hojas, pescados y productos tradicionales según cantidad de invitados.</td></tr></tbody></table></div>
<div style="background:#fff7ed;border:1px solid #fed7aa;border-radius:14px;padding:16px;margin:16px 0;"><h3 style="margin-top:0;">Nivel recomendado</h3><div style="margin:10px 0;"><div style="display:flex;justify-content:space-between;font-size:14px;"><strong>Hoja de bijao</strong><span>95%</span></div><div style="background:#e5e7eb;border-radius:999px;height:10px;"><div style="width:95%;height:10px;border-radius:999px;background:#16a34a;"></div></div></div><div style="margin:10px 0;"><div style="display:flex;justify-content:space-between;font-size:14px;"><strong>Paiche seco</strong><span>90%</span></div><div style="background:#e5e7eb;border-radius:999px;height:10px;"><div style="width:90%;height:10px;border-radius:999px;background:#16a34a;"></div></div></div><div style="margin:10px 0;"><div style="display:flex;justify-content:space-between;font-size:14px;"><strong>Pescado seco variado</strong><span>85%</span></div><div style="background:#e5e7eb;border-radius:999px;height:10px;"><div style="width:85%;height:10px;border-radius:999px;background:#16a34a;"></div></div></div><div style="margin:10px 0;"><div style="display:flex;justify-content:space-between;font-size:14px;"><strong>Frutas amazónicas</strong><span>65%</span></div><div style="background:#e5e7eb;border-radius:999px;height:10px;"><div style="width:65%;height:10px;border-radius:999px;background:#16a34a;"></div></div></div></div>
<h2>Conclusión</h2>
<p>La temporada de San Juan es una buena oportunidad para organizar tus compras con tiempo. Si necesitas productos para casa, restaurante o evento, consulta disponibilidad antes de la fecha para evitar apuros.</p>
<div style="background:#0f766e;color:#fff;padding:18px;border-radius:14px;margin-top:22px;"><h3 style="margin-top:0;color:#fff;">Consulta por WhatsApp</h3><p style="margin-bottom:0;">Para temporada de San Juan, escríbenos por WhatsApp con tu lista de productos y cantidad aproximada. Te confirmamos disponibilidad según stock.</p></div>
